+      }
+
+      .form-field input {
+        width: 1.25rem;
+        height: 1.25rem;
+        margin: 0.18rem 0 0;
+        accent-color: var(--primary);
+      }
+
+      .form-field label {
+        font-weight: 750;
+      }
+
+      .required-marker {
+        color: var(--danger);
+        font-weight: 800;
+      }
+
+      .helper-text,
+      .error-text {
+        grid-column: 2;
+        margin: 0;
+        font-size: 0.92rem;
+      }
+
+      .helper-text {
+        color: var(--muted);
+      }
+
+      .error-text {
+        color: var(--danger);
+        font-weight: 700;
+      }
+
+      .error-text[hidden] {
+        display: none;
+      }
+
+      .status {
+        min-height: 1.5rem;
+        margin: 0;
+        color: var(--success);
+        font-weight: 700;
+      }
+
