+        min-height: 3rem;
+        padding: 0.8rem 1.15rem;
+        color: #ffffff;
+        background: var(--primary);
+        border: 0;
+        border-radius: 999px;
+        box-shadow: 0 12px 24px rgb(36 87 214 / 24%);
+        font: inherit;
+        font-weight: 800;
+        cursor: pointer;
+      }
+
+      button:hover {
+        background: var(--primary-hover);
+      }
+
+      @media (forced-colors: active) {
+        .card,
+        .form-field,
+        button {
+          border: 1px solid CanvasText;
+        }
+
+        button {
+          forced-color-adjust: none;
+          color: ButtonText;
+          background: ButtonFace;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <a class="skip-link" href="#main-content">Skip to main content</a>
+    <main id="main-content" class="page-shell">
+      <div id="root"></div>
+    </main>
+
+    <script>
+      const termsUrl = "#terms";
+
+      function Header() {
+        return `
+          <p class="eyebrow">Account setup</p>
+          <h1>Review and continue</h1>
+          <p class="intro">
+            Confirm your agreement before submitting this consent form.
+          </p>
+        `;
+      }
+
+      function ConsentCheckbox() {
+        return `
+          <div class="form-field">
+            <input
+              id="terms-consent"
+              name="termsConsent"
+              type="checkbox"
+              required
+              aria-describedby="terms-help terms-error"
+            >
+            <label for="terms-consent">
+              I agree to the <a href="${termsUrl}">terms of use</a>
+              <span class="required-marker" aria-hidden="true">*</span>
+            </label>
