+            </p>
+          </div>
+        `;
+      }
+
+      function ConsentForm() {
+        return `
+          <form id="consent-form" novalidate>
+            <p class="required-note">
+              <span class="required-marker" aria-hidden="true">*</span> Required field
+            </p>
+            ${ConsentCheckbox()}
+            <p id="form-status" class="status" aria-live="polite"></p>
+            <button type="submit">Continue</button>
+          </form>
+        `;
+      }
+
+      function App() {
+        return `
+          <section class="card" aria-labelledby="page-title">
+            ${Header().replace("<h1>", '<h1 id="page-title">')}
+            ${ConsentForm()}
+          </section>
+        `;
+      }
+
+      document.querySelector("#root").innerHTML = App();
+
+      const form = document.querySelector("#consent-form");
+      const checkbox = document.querySelector("#terms-consent");
+      const error = document.querySelector("#terms-error");
+      const status = document.querySelector("#form-status");
+
+      function showConsentError() {
+        error.hidden = false;
+        checkbox.setAttribute("aria-invalid", "true");
+        status.textContent = "";
+      }
+
+      function clearConsentError() {
+        error.hidden = true;
+        checkbox.removeAttribute("aria-invalid");
+      }
+
+      form.addEventListener("submit", (event) => {
+        event.preventDefault();
+
+        if (!checkbox.checked) {
+          showConsentError();
+          checkbox.focus();
+          return;
+        }
+
+        clearConsentError();
+        status.textContent = "Thanks. Your consent is ready to submit.";
+      });
+
+      checkbox.addEventListener("change", () => {
+        if (checkbox.checked) {
+          clearConsentError();
+        }
+      });
+    </script>
+  </body>
+</html>
*** End Patch
