<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Terms consent form</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f4f7fb;
        --panel: #ffffff;
        --text: #172033;
        --muted: #5b6474;
        --border: #c9d2e3;
        --primary: #2457d6;
        --primary-hover: #1d46ad;
        --danger: #b42318;
        --success: #176b3a;
        --shadow: 0 24px 70px rgb(36 54 96 / 16%);
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        line-height: 1.5;
        color: var(--text);
        background:
          radial-gradient(circle at top left, rgb(36 87 214 / 16%), transparent 34rem),
          linear-gradient(135deg, #f8fbff 0%, var(--bg) 100%);
      }

      a {
        color: var(--primary);
        font-weight: 700;
        text-underline-offset: 0.16em;
      }

      a:hover {
        color: var(--primary-hover);
      }

      a:focus-visible,
      button:focus-visible,
      input:focus-visible {
        outline: 3px solid #111827;
        outline-offset: 3px;
      }

      .skip-link {
        position: absolute;
        top: 1rem;
        left: 1rem;
        z-index: 10;
        padding: 0.75rem 1rem;
        color: #ffffff;
        background: #111827;
        border-radius: 999px;
        transform: translateY(-160%);
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .page-shell {
        display: grid;
        min-height: 100vh;
        place-items: center;
        padding: 2rem 1rem;
      }

      .card {
        width: min(100%, 34rem);
        padding: clamp(1.5rem, 5vw, 3rem);
        background: var(--panel);
        border: 1px solid rgb(201 210 227 / 70%);
        border-radius: 1.5rem;
        box-shadow: var(--shadow);
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: var(--primary);
        font-size: 0.78rem;
        font-weight: 800;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 7vw, 3rem);
        line-height: 1.05;
        letter-spacing: -0.05em;
      }

      .intro {
        max-width: 28rem;
        margin: 1rem 0 2rem;
        color: var(--muted);
        font-size: 1rem;
      }

      form {
        display: grid;
        gap: 1.25rem;
      }

      .required-note {
        margin: 0;
        color: var(--muted);
        font-size: 0.9rem;
      }

      .form-field {
        display: grid;
        grid-template-columns: auto 1fr;
        gap: 0.25rem 0.85rem;
        padding: 1rem;
        border: 1px solid var(--border);
        border-radius: 1rem;
        background: #fbfdff;
      }

      .form-field input {
        width: 1.25rem;
        height: 1.25rem;
        margin: 0.18rem 0 0;
        accent-color: var(--primary);
      }

      .form-field label {
        font-weight: 750;
      }

      .required-marker {
        color: var(--danger);
        font-weight: 800;
      }

      .helper-text,
      .error-text {
        grid-column: 2;
        margin: 0;
        font-size: 0.92rem;
      }

      .helper-text {
        color: var(--muted);
      }

      .error-text {
        color: var(--danger);
        font-weight: 700;
      }

      .error-text[hidden] {
        display: none;
      }

      .status {
        min-height: 1.5rem;
        margin: 0;
        color: var(--success);
        font-weight: 700;
      }

      button {
        min-height: 3rem;
        padding: 0.8rem 1.15rem;
        color: #ffffff;
        background: var(--primary);
        border: 0;
        border-radius: 999px;
        box-shadow: 0 12px 24px rgb(36 87 214 / 24%);
        font: inherit;
        font-weight: 800;
        cursor: pointer;
      }

      button:hover {
        background: var(--primary-hover);
      }

      @media (forced-colors: active) {
        .card,
        .form-field,
        button {
          border: 1px solid CanvasText;
        }

        button {
          forced-color-adjust: none;
          color: ButtonText;
          background: ButtonFace;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content" class="page-shell">
      <div id="root"></div>
    </main>

    <script>
      const termsUrl = "#terms";

      function Header() {
        return `
          <p class="eyebrow">Account setup</p>
          <h1>Review and continue</h1>
          <p class="intro">
            Confirm your agreement before submitting this consent form.
          </p>
        `;
      }

      function ConsentCheckbox() {
        return `
          <div class="form-field">
            <input
              id="terms-consent"
              name="termsConsent"
              type="checkbox"
              required
              aria-describedby="terms-help terms-error"
            >
            <label for="terms-consent">
              I agree to the <a href="${termsUrl}">terms of use</a>
              <span class="required-marker" aria-hidden="true">*</span>
            </label>
            <p id="terms-help" class="helper-text">
              Required to create and use your account.
            </p>
            <p id="terms-error" class="error-text" hidden>
              Error: Agree to the terms of use before continuing.
            </p>
          </div>
        `;
      }

      function ConsentForm() {
        return `
          <form id="consent-form" novalidate>
            <p class="required-note">
              <span class="required-marker" aria-hidden="true">*</span> Required field
            </p>
            ${ConsentCheckbox()}
            <p id="form-status" class="status" aria-live="polite"></p>
            <button type="submit">Continue</button>
          </form>
        `;
      }

      function App() {
        return `
          <section class="card" aria-labelledby="page-title">
            ${Header().replace("<h1>", '<h1 id="page-title">')}
            ${ConsentForm()}
          </section>
        `;
      }

      document.querySelector("#root").innerHTML = App();

      const form = document.querySelector("#consent-form");
      const checkbox = document.querySelector("#terms-consent");
      const error = document.querySelector("#terms-error");
      const status = document.querySelector("#form-status");

      function showConsentError() {
        error.hidden = false;
        checkbox.setAttribute("aria-invalid", "true");
        status.textContent = "";
      }

      function clearConsentError() {
        error.hidden = true;
        checkbox.removeAttribute("aria-invalid");
      }

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        if (!checkbox.checked) {
          showConsentError();
          checkbox.focus();
          return;
        }

        clearConsentError();
        status.textContent = "Thanks. Your consent is ready to submit.";
      });

      checkbox.addEventListener("change", () => {
        if (checkbox.checked) {
          clearConsentError();
        }
      });
    </script>
  </body>
</html>
